							var ch = (q.choices || []).map(function (x) {
									return toText(r(x));
								}),
								ans = Number(r(q.answer));
							out.push("Q" + (i + 1) + ". " + t(q.question));
							ch.forEach(function (x, k) {
								out.push("   " + "ABCDEFGH"[k] + ") " + x);
							});
